<?php
namespace App\Http\Controllers;
use App\Services\CcsWebsiteContent;
use App\Services\CcsAdministration;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
class CcsWebsiteContentController extends Controller {
 public function index(Request $r,CcsWebsiteContent $cms){$cms->authorize($r->user());$kind=$r->query('kind','ads');abort_unless(isset($cms::KINDS[$kind]),404);$rows=$cms->rows($kind);$editing=$r->filled('edit')?$rows->firstWhere('id',(int)$r->edit):null;if($r->filled('edit'))abort_unless($editing,404);return view('ccs.website-content',compact('rows','editing','kind'));}
 public function feed(CcsWebsiteContent $cms){$json=json_encode($cms->publicData(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);return response('window.CCS_CONTENT='.$json.';',200,['Content-Type'=>'application/javascript; charset=UTF-8','Cache-Control'=>'no-store','X-Content-Type-Options'=>'nosniff']);}
 public function save(Request $r,CcsWebsiteContent $cms){
  $cms->authorize($r->user());$v=$r->validate(['id'=>'nullable|integer|min:1','revision'=>'nullable|integer|min:1','kind'=>'required|in:ads,models,videos,offers','title'=>'required|string|max:180','active'=>'nullable|boolean','sort_order'=>'required|integer|min:0|max:9999','description'=>'nullable|string|max:4000','subtitle'=>'nullable|string|max:180','kicker'=>'nullable|string|max:180','discount'=>'nullable|numeric|min:0|max:100','discount_label'=>'nullable|string|max:120','terms'=>'nullable|string|max:1000','service'=>'nullable|string|max:150','cta_label'=>'nullable|string|max:100','cta_url'=>'nullable|string|max:1500','alt'=>'nullable|string|max:250','make'=>'nullable|string|max:80','model'=>'nullable|string|max:120','code'=>'nullable|string|max:80','type'=>['nullable',\Illuminate\Validation\Rule::in(['EV', 'HEV', 'HEV / PHEV', 'HEV/PHEV', 'ICE', 'IMA', 'IMA / HEV', 'IMA / i-DCD / HEV', 'MHEV', 'MHEV/HEV', 'PHEV', 'SERIES HEV', 'Series hybrid', 'e:HEV', 'i-DCD', 'i-DCD / e:HEV'])],'platform'=>'nullable|in:video,facebook,instagram,tiktok,youtube','url'=>'nullable|string|max:1500','image_url'=>'nullable|string|max:1500','bullets'=>'nullable|string|max:2000','image'=>'nullable|image|mimes:jpg,jpeg,png,webp,avif|max:10240','video'=>'nullable|file|mimes:mp4,webm|max:102400']);
  $kind=$v['kind'];$existing=!empty($v['id'])?DB::table('ccs_website_content')->where('id',$v['id'])->where('kind',$kind)->first():null;if(!empty($v['id']))abort_unless($existing,404);if($existing&&((int)($v['revision']??0)!==(int)$existing->revision))throw ValidationException::withMessages(['title'=>'Another user changed this card. Reload before editing.']);
  $data=$existing?json_decode($existing->data,true):[];foreach(['description','subtitle','kicker','discount','discount_label','terms','service','cta_label','alt'] as $key)$data[$key]=$v[$key]??'';
  if($kind==='models'){foreach(['make','model','code','type'] as $key){if(empty($v[$key]))throw ValidationException::withMessages([$key=>'This field is required.']);$data[$key]=$v[$key];}}
  if($kind==='offers')$data['bullets']=array_slice(array_values(array_filter(array_map('trim',preg_split('/\R/',$v['bullets']??'')))),0,20);
  if(!empty($v['cta_url'])){$u=$v['cta_url'];if(!preg_match('~^(?:contact|index)\.html(?:[?#].*)?$~',$u))$u=$cms->safeUrl($u);$data['cta_url']=$u;}else $data['cta_url']='';
  $created=[];try{
   foreach(['image','video'] as $field)if($r->hasFile($field)){$file=$r->file($field);$relative=$kind.'/'.Str::uuid().'.'.$file->extension();$root=$cms->mediaRoot();if(!is_dir($root.'/'.$kind))mkdir($root.'/'.$kind,0755,true);$file->move($root.'/'.$kind,basename($relative));$created[]=$root.'/'.$relative;$data[$field==='image'?'image':'url']=$cms->mediaUrl($relative);if($field==='image')$data['full_image']=$data['image'];}
   if(!$r->hasFile('image')&&!empty($v['image_url'])){$data['image']=$cms->safeUrl($v['image_url']);$data['full_image']=$data['image'];}
   if($kind==='videos'){$data['platform']=$v['platform']??'video';if(!$r->hasFile('video'))$data['url']=$cms->safeUrl($v['url']??'',true);elseif($data['platform']!=='video')throw ValidationException::withMessages(['platform'=>'Choose Direct video when uploading a file.']);$data['embed_url']=$cms->embed($data['platform'],$data['url']);$data['asset']=$data['image']??'';}
   elseif($kind!=='models'&&empty($data['image']))throw ValidationException::withMessages(['image'=>'Upload an image or enter an HTTPS image URL.']);
   DB::transaction(function()use($r,$v,$kind,$existing,$data){$record=['kind'=>$kind,'title'=>$v['title'],'active'=>$r->boolean('active'),'sort_order'=>$v['sort_order'],'data'=>json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),'updated_by'=>$r->user()->id,'updated_at'=>now()];if($existing){$record['revision']=$existing->revision+1;$n=DB::table('ccs_website_content')->where('id',$existing->id)->where('revision',$existing->revision)->update($record);if(!$n)throw ValidationException::withMessages(['title'=>'This card changed. Reload before saving.']);$id=$existing->id;}else{$record+=['slug'=>$kind.'-'.Str::uuid(),'created_at'=>now()];$id=DB::table('ccs_website_content')->insertGetId($record);}app(CcsAdministration::class)->audit($r->user()->id,'website_content_saved','website_content',$id,['kind'=>$kind,'active'=>$record['active']]);});
  }catch(\Throwable $e){foreach($created as $path)@unlink($path);throw $e;}
  return redirect()->route('ccs.website.content',['kind'=>$kind])->with('success','Website card saved.');
 }
 public function toggle(Request $r,int $id,CcsWebsiteContent $cms){$cms->authorize($r->user());$v=$r->validate(['active'=>'required|boolean','revision'=>'required|integer|min:1']);DB::transaction(function()use($r,$id,$v){$n=DB::table('ccs_website_content')->where('id',$id)->where('revision',$v['revision'])->update(['active'=>$r->boolean('active'),'revision'=>$v['revision']+1,'updated_by'=>$r->user()->id,'updated_at'=>now()]);if(!$n)throw ValidationException::withMessages(['active'=>'This card changed. Reload before changing status.']);app(CcsAdministration::class)->audit($r->user()->id,'website_content_status','website_content',$id,['active'=>$r->boolean('active')]);});return back()->with('success','Website card status updated.');}
}
